<template>
  <el-dialog
    v-model="visible"
    :title="isEdit ? t('heal.rules.form.editTitle') : t('heal.rules.form.createTitle')"
    width="720px"
    :close-on-click-modal="false"
    @closed="onClosed"
  >
    <el-form ref="formRef" :model="form" :rules="rules" label-width="130px">
      <el-form-item :label="t('heal.rules.form.ruleName')" prop="name">
        <el-input v-model="form.name" :placeholder="t('heal.rules.form.namePlaceholder')" />
      </el-form-item>
      <el-form-item :label="t('heal.rules.form.alertRule')" prop="alert_rule_id">
        <el-select v-model="form.alert_rule_id" :placeholder="t('heal.rules.form.alertRulePlaceholder')" style="width: 100%">
          <el-option
            v-for="rule in alertRules"
            :key="rule.id"
            :label="rule.name"
            :value="rule.id"
          />
        </el-select>
      </el-form-item>
      <el-form-item :label="t('heal.rules.form.action')" prop="action_id">
        <el-select v-model="form.action_id" :placeholder="t('heal.rules.form.actionPlaceholder')" style="width: 100%">
          <el-option
            v-for="action in healActions"
            :key="action.action_id"
            :label="`${actionDisplayName(action)} (${action.action_id})`"
            :value="action.action_id"
          />
        </el-select>
      </el-form-item>
      <el-form-item :label="t('heal.rules.form.actionParams')">
        <JsonEditor
          v-model="form.action_params"
          :rows="6"
          :placeholder="t('heal.rules.form.actionParamsPlaceholder')"
        />
      </el-form-item>
      <el-form-item :label="t('heal.rules.form.verificationConfig')">
        <JsonEditor v-model="form.verification_config" :rows="4" :placeholder="t('common.optional')" />
      </el-form-item>
      <el-form-item :label="t('heal.autoExecute')">
        <el-switch v-model="form.auto_execute" />
      </el-form-item>
      <el-form-item :label="t('heal.rules.form.enableRule')">
        <el-switch v-model="form.enabled" />
      </el-form-item>
      <el-form-item :label="t('heal.rules.form.priority')">
        <el-input-number v-model="form.priority" :min="0" />
      </el-form-item>
      <el-form-item :label="t('common.description')">
        <el-input v-model="form.description" type="textarea" :rows="3" :placeholder="t('common.optional')" />
      </el-form-item>
    </el-form>

    <template #footer>
      <el-button @click="visible = false">{{ t('common.cancel') }}</el-button>
      <el-button type="primary" :loading="submitting" @click="onSubmit">
        {{ isEdit ? t('common.save') : t('common.create') }}
      </el-button>
    </template>
  </el-dialog>
</template>

<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage, type FormInstance, type FormRules } from 'element-plus'
import {
  createHealRule,
  updateHealRule,
  type HealRuleCreate,
  type HealRuleRead,
} from '@/api/healRules'
import { getAlertRules, type AlertRuleRead } from '@/api/alertRules'
import { getHealActions, type HealActionRead } from '@/api/healActions'
import JsonEditor from '@/components/common/JsonEditor.vue'
import { showError } from '@/utils/error'
import { actionDisplayName } from '@/utils/actionName'

const { t } = useI18n()

const props = defineProps<{
  modelValue: boolean
  rule?: HealRuleRead | null
}>()

const emit = defineEmits<{
  'update:modelValue': [value: boolean]
  success: []
}>()

const visible = ref(props.modelValue)
const submitting = ref(false)
const formRef = ref<FormInstance>()
const alertRules = ref<AlertRuleRead[]>([])
const healActions = ref<HealActionRead[]>([])
const isEdit = ref(false)

const form = ref<{
  name: string
  description: string
  alert_rule_id: number | undefined
  action_id: string
  action_params: Record<string, unknown>
  verification_config: Record<string, unknown>
  auto_execute: boolean
  enabled: boolean
  priority: number
}>({
  name: '',
  description: '',
  alert_rule_id: undefined,
  action_id: '',
  action_params: {},
  verification_config: {},
  auto_execute: false,
  enabled: true,
  priority: 0,
})

const rules: FormRules = {
  name: [{ required: true, message: () => t('heal.rules.form.nameRequired'), trigger: 'blur' }],
  alert_rule_id: [{ required: true, message: () => t('heal.rules.form.alertRuleRequired'), trigger: 'change' }],
  action_id: [{ required: true, message: () => t('heal.rules.form.actionRequired'), trigger: 'change' }],
}

watch(
  () => props.modelValue,
  (val) => {
    visible.value = val
  }
)

watch(
  () => props.rule,
  (rule) => {
    if (rule) {
      isEdit.value = true
      form.value = {
        name: rule.name,
        description: rule.description || '',
        alert_rule_id: rule.alert_rule_id,
        action_id: rule.action_id,
        action_params: rule.action_params || {},
        verification_config: rule.verification_config || {},
        auto_execute: rule.auto_execute,
        enabled: rule.enabled,
        priority: rule.priority,
      }
    } else {
      isEdit.value = false
      resetForm()
    }
  },
  { immediate: true }
)

onMounted(() => {
  loadOptions()
})

async function loadOptions() {
  try {
    const [rulesRes, actionsRes] = await Promise.all([
      getAlertRules({ page_size: 100 }),
      getHealActions(),
    ])
    alertRules.value = rulesRes.items
    healActions.value = actionsRes
  } catch (error) {
    showError(error, t('common.loadOptionsFailed'))
  }
}

function resetForm() {
  form.value = {
    name: '',
    description: '',
    alert_rule_id: undefined,
    action_id: '',
    action_params: {},
    verification_config: {},
    auto_execute: false,
    enabled: true,
    priority: 0,
  }
}

function onClosed() {
  emit('update:modelValue', false)
  formRef.value?.resetFields()
  resetForm()
}

async function onSubmit() {
  const valid = await formRef.value?.validate().catch(() => false)
  if (!valid) return

  submitting.value = true
  try {
    const data: HealRuleCreate = {
      name: form.value.name,
      description: form.value.description || undefined,
      alert_rule_id: form.value.alert_rule_id as number,
      action_id: form.value.action_id,
      action_params: form.value.action_params,
      verification_config: form.value.verification_config,
      auto_execute: form.value.auto_execute,
      enabled: form.value.enabled,
      priority: form.value.priority,
    }
    if (props.rule) {
      await updateHealRule(props.rule.id, data)
    } else {
      await createHealRule(data)
    }
    ElMessage.success(isEdit.value ? t('heal.rules.form.ruleUpdated') : t('heal.rules.form.ruleCreated'))
    emit('success')
    visible.value = false
  } catch (error) {
    showError(error, isEdit.value ? t('heal.rules.form.updateFailed') : t('heal.rules.form.createFailed'))
  } finally {
    submitting.value = false
  }
}
</script>
