import apiClient from './client'

export interface HealRuleRead {
  id: number
  name: string
  description?: string | null
  alert_rule_id: number
  action_id: string
  action_params: Record<string, unknown>
  enabled: boolean
  auto_execute: boolean
  priority: number
  verification_config?: Record<string, unknown> | null
  created_at: string
  updated_at: string
}

export interface HealRuleCreate {
  name: string
  description?: string
  alert_rule_id: number
  action_id: string
  action_params?: Record<string, unknown>
  enabled?: boolean
  auto_execute?: boolean
  priority?: number
  verification_config?: Record<string, unknown>
}

export interface HealRuleUpdate {
  name?: string
  description?: string
  action_id?: string
  action_params?: Record<string, unknown>
  enabled?: boolean
  auto_execute?: boolean
  priority?: number
  verification_config?: Record<string, unknown>
}

export interface ToggleResponse {
  id: number
  enabled: boolean
}

export async function getHealRules(): Promise<HealRuleRead[]> {
  const response = await apiClient.get<HealRuleRead[]>('/v1/heal-rules')
  return response.data
}

export async function createHealRule(data: HealRuleCreate): Promise<HealRuleRead> {
  const response = await apiClient.post<HealRuleRead>('/v1/heal-rules', data)
  return response.data
}

export async function getHealRule(ruleId: number): Promise<HealRuleRead> {
  const response = await apiClient.get<HealRuleRead>(`/v1/heal-rules/${ruleId}`)
  return response.data
}

export async function updateHealRule(
  ruleId: number,
  data: HealRuleUpdate
): Promise<HealRuleRead> {
  const response = await apiClient.put<HealRuleRead>(`/v1/heal-rules/${ruleId}`, data)
  return response.data
}

export async function deleteHealRule(ruleId: number): Promise<void> {
  await apiClient.delete(`/v1/heal-rules/${ruleId}`)
}

export async function toggleHealRule(ruleId: number): Promise<ToggleResponse> {
  const response = await apiClient.post<ToggleResponse>(`/v1/heal-rules/${ruleId}/toggle`)
  return response.data
}
