<template>
  <div class="page-heal-rule-list">
    <CrudToolbar :title="t('heal.rules.title')" :can-create="authStore.isAdmin" @create="onCreate" />

    <el-card>
      <DataTable v-model:current-page="page" v-model:page-size="pageSize" :data="rules" :loading="loading">
        <el-table-column prop="name" :label="t('common.name')" min-width="180" />
        <el-table-column prop="alert_rule_id" :label="t('heal.rules.alertRuleId')" width="120" />
        <el-table-column prop="action_id" :label="t('heal.actionId')" min-width="160" />
        <el-table-column prop="auto_execute" :label="t('heal.autoExecute')" width="100">
          <template #default="{ row }">
            <el-tag :type="row.auto_execute ? 'success' : 'info'" size="small">
              {{ row.auto_execute ? t('common.yes') : t('common.no') }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="enabled" :label="t('common.status')" width="100">
          <template #default="{ row }">
            <el-tag :type="row.enabled ? 'success' : 'info'" size="small">
              {{ row.enabled ? t('common.enabled') : t('common.disabled') }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column :label="t('common.actions')" width="220" fixed="right">
          <template #default="{ row }">
            <el-button v-if="authStore.isAdmin" link type="primary" size="small" @click="onEdit(row)">
              {{ t('common.edit') }}
            </el-button>
            <el-button v-if="authStore.isAdmin" link type="primary" size="small" @click="onToggle(row)">
              {{ row.enabled ? t('common.disable') : t('common.enable') }}
            </el-button>
            <ConfirmButton
              v-if="authStore.isAdmin"
              :title="t('heal.rules.confirmDelete')"
              confirm-button-type="danger"
              @confirm="onDelete(row)"
            >
              <el-button link type="danger" size="small">{{ t('common.delete') }}</el-button>
            </ConfirmButton>
          </template>
        </el-table-column>
      </DataTable>
    </el-card>

    <HealRuleFormDialog v-model="dialogVisible" :rule="selectedRule" @success="loadRules" />
  </div>
</template>

<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage } from 'element-plus'
import { useAuthStore } from '@/stores/auth'
import { deleteHealRule, getHealRules, toggleHealRule, type HealRuleRead } from '@/api/healRules'
import ConfirmButton from '@/components/common/ConfirmButton.vue'
import HealRuleFormDialog from './HealRuleFormDialog.vue'
import DataTable from '@/components/common/DataTable.vue'
import CrudToolbar from '@/components/common/CrudToolbar.vue'
import { showError } from '@/utils/error'

const { t } = useI18n()
const authStore = useAuthStore()

const rules = ref<HealRuleRead[]>([])
const loading = ref(false)
const dialogVisible = ref(false)
const selectedRule = ref<HealRuleRead | null>(null)
const page = ref(1)
const pageSize = ref(10)

async function loadRules() {
  loading.value = true
  try {
    rules.value = await getHealRules()
  } catch (error) {
    showError(error, t('heal.rules.loadFailed'))
  } finally {
    loading.value = false
  }
}

function onCreate() {
  selectedRule.value = null
  dialogVisible.value = true
}

function onEdit(row: HealRuleRead) {
  selectedRule.value = row
  dialogVisible.value = true
}

async function onToggle(row: HealRuleRead) {
  try {
    await toggleHealRule(row.id)
    ElMessage.success(t('common.statusUpdated'))
    loadRules()
  } catch (error) {
    showError(error, t('common.toggleFailed'))
  }
}

async function onDelete(row: HealRuleRead) {
  try {
    await deleteHealRule(row.id)
    ElMessage.success(t('heal.rules.deleted'))
    loadRules()
  } catch (error) {
    showError(error, t('common.deleteFailed'))
  }
}

onMounted(() => {
  loadRules()
})
</script>

